<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import type { AgentWorkflowCodeBinding, AgentWorkflowCodePolicy, AgentWorkflowCodeSpec, AgentWorkflowNodeResources, AgentWorkflowResourceCatalog, AgentWorkflowStep } from '@/api/agentWorkflows';
import { defaultWorkflowRepeat } from '@/agent/agentWorkflowRepeat';
import { workflowNodeResourceRows } from '@/agent/agentWorkflowEditor';
import AgentWorkflowCodeConfig from './AgentWorkflowCodeConfig.vue';
const props=defineProps<{modelValue:AgentWorkflowStep;disabled?:boolean;variables?:{value:string;label:string}[];catalog?:AgentWorkflowResourceCatalog;snapshot?:AgentWorkflowNodeResources;historical?:boolean;resourcesLoading?:boolean;resourcesError?:string}>();
const emit=defineEmits<{'update:modelValue':[AgentWorkflowStep];validity:[boolean];refreshResources:[]}>();
const {t}=useI18n();const tr=(key:string)=>t(`agentWorkflowCanvas.${key}`);
const iteration=computed(()=>props.modelValue.kind==='iteration'),spec=computed(()=>iteration.value?props.modelValue.iteration:props.modelValue.loop),body=computed(()=>spec.value?.body);
const binding=computed(()=>iteration.value?props.modelValue.iteration?.items:props.modelValue.loop?.initial);
const raw=ref(''),rawInvalid=ref(false),codeValid=ref(true);
const bodyVariables=computed(()=>[...(props.variables||[]),...(iteration.value?[{value:'{{ iteration.item }}',label:tr('repeatCurrentItem')},{value:'{{ iteration.index }}',label:tr('repeatCurrentIndex')}]:[{value:'{{ loop.state }}',label:tr('loopState')},{value:'{{ loop.index }}',label:tr('repeatCurrentIndex')}])]);
const references=computed(()=>(props.variables||[]).map(item=>({...item,value:item.value.replace(/^\{\{\s*|\s*\}\}$/g,'')})));
const resources=computed(()=>body.value?(['skills','shortcuts'] as const).map(field=>({field,rows:workflowNodeResourceRows(body.value!,field,props.catalog,props.snapshot,props.historical)})):[]);
watch(()=>JSON.stringify(binding.value?.value),value=>{raw.value=value===undefined?(iteration.value?'[]':'{}'):JSON.stringify(JSON.parse(value),null,2);rawInvalid.value=false;},{immediate:true});
watch([rawInvalid,codeValid],()=>emit('validity',!rawInvalid.value&&codeValid.value),{immediate:true});
function update(change:(next:AgentWorkflowStep)=>void){if(props.disabled)return;const next:AgentWorkflowStep=JSON.parse(JSON.stringify(props.modelValue));change(next);emit('update:modelValue',next);}
function editSpec(change:(value:NonNullable<AgentWorkflowStep['iteration']>|NonNullable<AgentWorkflowStep['loop']>)=>void){update(next=>{const value=iteration.value?next.iteration:next.loop;if(value)change(value);});}
function editBinding(change:(value:AgentWorkflowCodeBinding)=>void){update(next=>{const value=iteration.value?next.iteration?.items:next.loop?.initial;if(value)change(value);});}
function mode(source:boolean){rawInvalid.value=false;editBinding(value=>{if(source){delete value.value;value.source='';}else{delete value.source;value.value=iteration.value?[]:{};}});}
function literal(value:string){if(props.disabled)return;raw.value=value;try{const parsed:unknown=JSON.parse(value);if(iteration.value?!Array.isArray(parsed):!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw Error();rawInvalid.value=false;editBinding(row=>row.value=parsed);}catch{rawInvalid.value=true;}}
function bodyKind(kind:'agent'|'code'){codeValid.value=true;update(next=>{const target=iteration.value?next.iteration:next.loop;if(!target)return;target.body=kind==='agent'?{id:'body',kind:'agent',task:t('uiCoverage.workflow.defaultRepeatTask',{item:'{{ iteration.item }}'})}:defaultWorkflowRepeat(iteration.value?'iteration':'loop')[iteration.value?'iteration':'loop']!.body;});}
function setCode(code:AgentWorkflowCodeSpec){editSpec(value=>{value.body.code=code;});}
function setPolicy(policy:AgentWorkflowCodePolicy|undefined){editSpec(value=>{if(policy)value.body.policy=policy;else delete value.body.policy;});}
function resource(field:'skills'|'shortcuts',id:string,checked:boolean){editSpec(value=>{value.body[field]=checked?[...new Set([...(value.body[field]||[]),id])]:(value.body[field]||[]).filter(item=>item!==id);});}
function until(field:'source'|'operator'|'value',value:string){update(next=>{if(!next.loop)return;Object.assign(next.loop.until,{[field]:value});if(field==='operator'&&['is_empty','not_empty'].includes(value))delete next.loop.until.value;});}
</script>
<template>
  <section v-if="spec&&body&&binding" class="aw-repeat-config" data-testid="workflow-repeat-config">
    <p class="aw-repeat-hint">{{tr(iteration?'iterationHint':'loopHint')}}</p>
    <label>{{tr(iteration?'iterationItems':'loopInitial')}}<select :value="Object.prototype.hasOwnProperty.call(binding,'value')?'value':'source'" :disabled="disabled" @change="mode(($event.target as HTMLSelectElement).value==='source')"><option value="source">{{tr('codeUpstream')}}</option><option value="value">{{tr('codeFixedValue')}}</option></select></label>
    <template v-if="!Object.prototype.hasOwnProperty.call(binding,'value')"><select :value="binding.source||''" :disabled="disabled" :aria-label="tr('codeChooseSource')" @change="editBinding(row=>row.source=($event.target as HTMLSelectElement).value)"><option value="">{{tr('codeChooseSource')}}</option><option v-for="item in references" :key="item.value" :value="item.value">{{item.label}} · {{item.value}}</option></select><input :value="binding.source||''" :disabled="disabled" :aria-label="tr('codeReference')" @input="editBinding(row=>row.source=($event.target as HTMLInputElement).value)" /></template>
    <textarea v-else :value="raw" :disabled="disabled" rows="4" spellcheck="false" data-testid="workflow-repeat-data" @input="literal(($event.target as HTMLTextAreaElement).value)" />
    <p v-if="rawInvalid" class="aw-repeat-error" role="alert">{{tr(iteration?'iterationInvalidArray':'loopInvalidState')}}</p>
    <template v-if="iteration&&modelValue.iteration"><div class="aw-repeat-row"><label>{{tr('iterationConcurrency')}}<select :value="modelValue.iteration.concurrency??1" :disabled="disabled" @change="update(next=>next.iteration!.concurrency=Number(($event.target as HTMLSelectElement).value))"><option v-for="n in 10" :key="n" :value="n">{{n}}</option></select></label><label>{{tr('iterationMaxItems')}}<input type="number" min="1" max="100" :value="modelValue.iteration.max_items??100" :disabled="disabled" @change="update(next=>next.iteration!.max_items=Number(($event.target as HTMLInputElement).value))" /></label></div><label>{{tr('iterationItemFailure')}}<select :value="modelValue.iteration.on_item_error||'stop'" :disabled="disabled" @change="update(next=>next.iteration!.on_item_error=($event.target as HTMLSelectElement).value as 'stop'|'continue')"><option value="stop">{{tr('iterationStop')}}</option><option value="continue">{{tr('iterationContinue')}}</option></select></label></template>
    <template v-else-if="modelValue.loop"><label>{{tr('loopMaxIterations')}}<input type="number" min="1" max="100" :value="modelValue.loop.max_iterations" :disabled="disabled" @change="update(next=>next.loop!.max_iterations=Number(($event.target as HTMLInputElement).value))" /></label><fieldset class="aw-loop-condition"><legend>{{tr('loopUntil')}}</legend><label>{{tr('conditionSource')}}<input :value="modelValue.loop.until.source" :disabled="disabled" placeholder="loop.state.count" @input="until('source',($event.target as HTMLInputElement).value)" /></label><label>{{tr('conditionOperator')}}<select :value="modelValue.loop.until.operator" :disabled="disabled" @change="until('operator',($event.target as HTMLSelectElement).value)"><option v-for="operator in ['equals','not_equals','contains','not_contains','is_empty','not_empty','gt','gte','lt','lte']" :key="operator" :value="operator">{{tr(`operators.${operator}`)}}</option></select></label><label v-if="!['is_empty','not_empty'].includes(modelValue.loop.until.operator)">{{tr('conditionValue')}}<input :value="modelValue.loop.until.value||''" :disabled="disabled" @input="until('value',($event.target as HTMLInputElement).value)" /></label></fieldset></template>
    <section class="aw-repeat-body"><header><strong>{{tr(iteration?'repeatBody':'loopBody')}}</strong><select v-if="iteration" :value="body.kind" :disabled="disabled" :aria-label="tr('repeatBodyKind')" @change="bodyKind(($event.target as HTMLSelectElement).value as 'agent'|'code')"><option value="code">{{tr('code')}}</option><option value="agent">{{tr('agent')}}</option></select></header>
      <AgentWorkflowCodeConfig v-if="body.kind==='code'&&body.code" :model-value="body.code" :policy="body.policy" :variables="bodyVariables" :disabled="disabled" @update:model-value="setCode" @update:policy="setPolicy" @validity="codeValid=$event" />
      <template v-else-if="body.kind==='agent'"><p class="aw-repeat-hint">{{tr('iterationAgentHint')}}</p><label>{{tr('task')}}<textarea :value="body.task||''" :disabled="disabled" rows="6" data-testid="workflow-repeat-agent-task" @input="editSpec(value=>value.body.task=($event.target as HTMLTextAreaElement).value)" /></label><label>{{tr('output')}}<input :value="body.output_file||''" :disabled="disabled" @input="editSpec(value=>value.body.output_file=($event.target as HTMLInputElement).value)" /></label><p class="aw-repeat-hint">{{tr('iterationArtifactHint')}}</p>
        <details :open="!!body.skills?.length||!!body.shortcuts?.length"><summary>{{tr('nodeResources')}}</summary><p class="aw-repeat-hint">{{tr('inheritAgentResources')}}</p><button v-if="!disabled" type="button" :disabled="resourcesLoading" @click="emit('refreshResources')">{{tr(resourcesLoading?'resourcesLoading':'refreshResources')}}</button><p v-if="resourcesError" class="aw-repeat-error">{{resourcesError}}</p><section v-for="group in resources" :key="group.field" class="aw-repeat-resources"><strong>{{tr(`nodeResourceGroups.${group.field}`)}}</strong><label v-for="row in group.rows" :key="row.id" class="aw-repeat-resource"><input type="checkbox" :checked="row.selected" :disabled="disabled||!row.selected&&(!row.available||resourcesLoading||!!resourcesError||(body[group.field]?.length||0)>=32)" @change="resource(group.field,row.id,($event.target as HTMLInputElement).checked)" /><span>{{row.title}}<small v-if="row.reason||row.missing">{{row.reason||tr('resourceMissing')}}</small></span></label><p v-if="!group.rows.length" class="aw-repeat-hint">{{tr(historical?'noExplicitResources':'noAvailableResources')}}</p></section></details>
      </template>
    </section>
  </section>
</template>
<style scoped>
.aw-repeat-config{display:flex;flex-direction:column;gap:11px;min-width:0}.aw-repeat-config label{display:flex;flex-direction:column;gap:5px;font-size:12px}.aw-repeat-config input,.aw-repeat-config select,.aw-repeat-config textarea{width:100%;min-width:0;box-sizing:border-box;padding:8px;border:1px solid var(--el-border-color);border-radius:7px;background:var(--el-bg-color);color:var(--el-text-color-primary);font:inherit;font-size:12px}.aw-repeat-config textarea{resize:vertical;line-height:1.65}.aw-repeat-config>textarea{font-family:ui-monospace,monospace}.aw-repeat-row{display:grid;grid-template-columns:1fr 1fr;gap:9px}.aw-repeat-hint{margin:0;font-size:11px;line-height:1.65;color:var(--el-text-color-secondary)}.aw-repeat-error{margin:0;font-size:11px;color:var(--el-color-danger)}.aw-loop-condition{display:flex;flex-direction:column;gap:8px;border:1px solid var(--el-border-color-lighter);border-radius:8px;padding:10px}.aw-loop-condition legend{font-size:12px}.aw-repeat-body{padding-top:12px;border-top:1px solid var(--el-border-color-lighter);display:flex;flex-direction:column;gap:10px}.aw-repeat-body>header{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px}.aw-repeat-body>header select{width:auto;min-width:110px}.aw-repeat-config details{font-size:12px}.aw-repeat-config summary{cursor:pointer;margin-bottom:8px}.aw-repeat-config button{font:inherit;font-size:11px;padding:5px 7px;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-bg-color);color:var(--el-text-color-secondary);cursor:pointer}.aw-repeat-resources{margin-top:10px;display:flex;flex-direction:column;gap:6px}.aw-repeat-resources>strong{font-size:11px}.aw-repeat-resource{flex-direction:row!important;align-items:flex-start;padding:7px;border:1px solid var(--el-border-color-lighter);border-radius:7px}.aw-repeat-resource input{width:auto;margin:3px 0}.aw-repeat-resource span{min-width:0;overflow-wrap:anywhere}.aw-repeat-resource small{display:block;font-size:10px;color:var(--el-color-warning);margin-top:3px}
</style>
